'use strict';const isPurchase=document.body.dataset.receiptKind==='purchase',$=s=>document.querySelector(s);let page=0,requestNumber=0,active=null;
function el(tag,text){const node=document.createElement(tag);if(text!==undefined)node.textContent=text;return node;}
function invalidate(){requestNumber++;active=null;page=0;$('#receipts').replaceChildren();$('#receipt-count').textContent='';$('#previous').disabled=true;$('#next').disabled=true;$('#receipt-search-submit').disabled=false;}
function readFilters(){return ReceiptSearch.filters({number:$('#receipt-number').value,from:$('#receipt-from').value,to:$('#receipt-to').value,query:$('#receipt-query').value},isPurchase);}
async function load(){if(!KashierData.loggedIn()){location.replace('auth.html?next='+(isPurchase?'purchase-receipts.html':'receipts.html'));return;}const request=++requestNumber;$('#receipts-status').textContent='پسوولەکان دەخوێندرێنەوە…';$('#receipts').replaceChildren();$('#receipt-count').textContent='';$('#previous').disabled=true;$('#next').disabled=true;$('#receipt-search-submit').disabled=true;try{const result=await KashierData.searchReceipts(isPurchase?'purchase':'sale',page,active);if(request!==requestNumber)return;ReceiptSearch.validate(result,isPurchase);for(const receipt of result.rows){const row=el('tr'),name=isPurchase?receipt.supplier_name:receipt.customer_name,extra=isPurchase?(receipt.invoice_no?' · فاتورە: '+receipt.invoice_no:''):(receipt.payment_mode==='credit'?' · قەرز':'');for(const value of [(isPurchase?'P-':'K-')+receipt.receipt_no,new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Baghdad',dateStyle:'short',timeStyle:'short'}).format(new Date(receipt.created_at)),(name||'—')+extra,new Intl.NumberFormat('en-US').format(BigInt(receipt.total))])row.append(el('td',value));const action=el('td'),link=el('a','بینین و چاپ');link.className='catalog-link';link.href=(isPurchase?'purchase-receipt.html?id=':'receipt.html?id=')+receipt.id;action.append(link);row.append(action);$('#receipts').append(row);}$('#receipt-count').textContent='کۆی ئەنجامەکان: '+new Intl.NumberFormat('en-US').format(BigInt(result.total))+' · پەڕە: '+(page+1);$('#receipts-status').textContent=result.rows.length?'':'هیچ پسوولەیەک لەم گەڕانەدا نەدۆزرایەوە.';$('#previous').disabled=page===0;$('#next').disabled=BigInt((page+1)*50)>=BigInt(result.total);}catch(error){if(request===requestNumber){$('#receipts').replaceChildren();$('#receipts-status').textContent=error.message;}}finally{if(request===requestNumber)$('#receipt-search-submit').disabled=false;}}
function search(){invalidate();try{active=readFilters();load();}catch(error){$('#receipts-status').textContent=error.message;}}
$('#receipt-search-form').addEventListener('submit',event=>{event.preventDefault();search();});for(const id of ['receipt-number','receipt-from','receipt-to','receipt-query'])$('#'+id).addEventListener('input',()=>{invalidate();$('#receipts-status').textContent='بۆ ئەم هەڵبژاردنانە دوگمەی گەڕان دابگرە.';});$('#receipt-clear').addEventListener('click',()=>{for(const id of ['receipt-number','receipt-from','receipt-to','receipt-query'])$('#'+id).value='';search();});$('#previous').addEventListener('click',()=>{if(active&&!$('#previous').disabled&&page>0){page--;load();}});$('#next').addEventListener('click',()=>{if(active&&!$('#next').disabled){page++;load();}});search();
